--
-- Table structure for table `t_classify_personal_di`
--

DROP TABLE IF EXISTS `t_classify_personal_di`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_classify_personal_di` (
  `id` varchar(36) NOT NULL COMMENT '唯一主键',
  `di_id` varchar(255) NOT NULL COMMENT '数据清单ID',
  `di_effective` tinyint NOT NULL COMMENT '数据清单有效性：0失效，1有效',
  `data_item_id` varchar(255) NOT NULL COMMENT '数据项ID',
  `data_item_name` varchar(2000) NOT NULL COMMENT '数据项名称',
  `data_item_name_en` varchar(2000) NOT NULL COMMENT '数据项名称英文',
  `data_item_effective` tinyint NOT NULL COMMENT '数据项有效性：0失效，1有效',
  `l1_class_id` varchar(255) DEFAULT NULL COMMENT '一级分类ID',
  `l1_class_name_cn` varchar(255) DEFAULT NULL COMMENT '一级分类中文',
  `l1_class_name_en` varchar(255) DEFAULT NULL COMMENT '一级分类英文',
  `l1_class_effective` tinyint DEFAULT NULL COMMENT '一级分类有效性：0失效，1有效',
  `l2_class_id` varchar(255) DEFAULT NULL COMMENT '二级分类ID',
  `l2_class_name_cn` varchar(255) DEFAULT NULL COMMENT '二级分类中文',
  `l2_class_name_en` varchar(255) DEFAULT NULL COMMENT '二级分类英文',
  `l2_class_effective` tinyint DEFAULT NULL COMMENT '二级分类有效性：0失效，1有效',
  `l3_class_id` varchar(255) DEFAULT NULL COMMENT '三级分类ID',
  `l3_class_name_cn` varchar(255) DEFAULT NULL COMMENT '三级分类中文',
  `l3_class_name_en` varchar(255) DEFAULT NULL COMMENT '三级分类英文',
  `l3_class_effective` tinyint DEFAULT NULL COMMENT '三级分类有效性：0失效，1有效',
  `confidentiality_level_name_cn` varchar(255) DEFAULT NULL COMMENT '机密性等级中文',
  `confidentiality_level_name_en` varchar(255) DEFAULT NULL COMMENT '机密性等级英文',
  `qlink_name_cn` varchar(255) DEFAULT NULL COMMENT '准标识连接性范围中文',
  `qlink_name_en` varchar(255) DEFAULT NULL COMMENT '准标识连接性范围英文',
  `sensitivity_level_name_cn` varchar(255) DEFAULT NULL COMMENT '敏感度级别中文',
  `sensitivity_level_name_en` varchar(255) DEFAULT NULL COMMENT '敏感度级别英文',
  `business_process_name` varchar(255) DEFAULT NULL COMMENT '场景名称',
  `business_process_name_en` varchar(255) DEFAULT NULL COMMENT '场景名称英文',
  `business_process_effective` tinyint DEFAULT NULL COMMENT '场景有效性：0失效，1有效',
  `purpose` varchar(2000) DEFAULT NULL COMMENT '目的',
  `purpose_cn` varchar(2000) DEFAULT NULL COMMENT '目的中文',
  `expiration_time` varchar(255) DEFAULT NULL COMMENT '软删除数据过期时间（过期后将自动删除，不再提供）',
  `product_id` varchar(255) DEFAULT NULL COMMENT '产品ID',
  `process_type` varchar(255) DEFAULT NULL COMMENT '处理方式',
  `process_type_name_cn` varchar(255) DEFAULT NULL COMMENT '处理方式中文',
  `process_type_name_en` varchar(255) DEFAULT NULL COMMENT '处理方式英文',
  `storage_mode_cn` varchar(255) DEFAULT NULL COMMENT '存储模式中文',
  `storage_mode_en` varchar(255) DEFAULT NULL COMMENT '存储模式英文',
  `pii_type` varchar(255) DEFAULT NULL COMMENT '标识符属性0-非标识符；1-标识符；2-准标识符',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='个人数据DI项';
/*!40101 SET character_set_client = @saved_cs_client */;

